<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import * as T from 'three';
import land from './game/earth-land.json';
const props=defineProps({from:Object,to:Object});const emit=defineEmits(['finish']);const canvas=ref(null),progress=ref(0),depart=ref({x:0,y:0}),arrival=ref({x:0,y:0});let renderer,scene,geometry,texture,material,frame,started,observer,hiddenAt,pausedMs=0,disposed=false;
const status=computed(()=>progress.value<.18?'DEPARTING':progress.value<.87?'IN TRANSIT':'ARRIVING');
const ll=(lat,lon,r=1)=>{const a=lat*Math.PI/180,b=lon*Math.PI/180;return new T.Vector3(Math.cos(a)*Math.sin(b),Math.sin(a),Math.cos(a)*Math.cos(b)).multiplyScalar(r);};
function visibility(){if(document.hidden)hiddenAt=performance.now();else if(hiddenAt){pausedMs+=performance.now()-hiddenAt;hiddenAt=null;}}
onMounted(()=>{
 const target=canvas.value;renderer=new T.WebGLRenderer({canvas:target,antialias:true,alpha:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;scene=new T.Scene();const camera=new T.PerspectiveCamera(37,1,.1,10);camera.position.z=3.8;
 const atlas=document.createElement('canvas');atlas.width=1024;atlas.height=512;const c=atlas.getContext('2d');c.fillStyle='#6d91a0';c.fillRect(0,0,1024,512);c.fillStyle='#bec9b2';c.strokeStyle='#a7bcae';c.lineWidth=.7;for(const ring of land){c.beginPath();ring.forEach(([lon,lat],i)=>{const x=(lon+180)/360*1024,y=(90-lat)/180*512;i?c.lineTo(x,y):c.moveTo(x,y);});c.closePath();c.fill();c.stroke();}
 texture=new T.CanvasTexture(atlas);texture.colorSpace=T.SRGBColorSpace;geometry=new T.SphereGeometry(1,64,40);const uv=geometry.attributes.uv,p=geometry.attributes.position;for(let i=0;i<p.count;i++)uv.setXY(i,(Math.atan2(p.getX(i),p.getZ(i))+Math.PI)/(2*Math.PI),.5+Math.asin(p.getY(i))/Math.PI);material=new T.MeshPhongMaterial({map:texture,shininess:11,specular:'#647c80'});
 const group=new T.Group();scene.add(group);group.add(new T.Mesh(geometry,material));scene.add(new T.AmbientLight('#b8d7e5',1.4));const key=new T.DirectionalLight('#fff7e9',2.5);key.position.set(-3,4,5);scene.add(key);
 const from=ll(props.from.lat,props.from.lon,1.02),to=ll(props.to.lat,props.to.lon,1.02),mid=from.clone().add(to).normalize();group.quaternion.setFromUnitVectors(mid,new T.Vector3(0,.10,1).normalize());
 const pinMaterial=new T.MeshBasicMaterial({color:'#eaf8f7'}),pinGeometry=new T.SphereGeometry(.018,12,8);for(const point of [from,to]){const pin=new T.Mesh(pinGeometry,pinMaterial);pin.position.copy(point);group.add(pin);}
 const angle=from.angleTo(to),route=t=>{if(angle<.0001)return from.clone();return from.clone().multiplyScalar(Math.sin((1-t)*angle)).addScaledVector(to,Math.sin(t*angle)).multiplyScalar(1/Math.sin(angle)).normalize().multiplyScalar(1.035+Math.sin(t*Math.PI)*.07);};
 const dots=[];for(let i=0;i<=40;i++)dots.push(...route(i/40).toArray());const dotGeometry=new T.BufferGeometry();dotGeometry.setAttribute('position',new T.Float32BufferAttribute(dots,3));const dotMaterial=new T.PointsMaterial({color:'#101b20',size:.011,sizeAttenuation:true});group.add(new T.Points(dotGeometry,dotMaterial));
 const shape=new T.Shape();shape.moveTo(0,.07);shape.lineTo(.013,.015);shape.lineTo(.06,-.016);shape.lineTo(.06,-.03);shape.lineTo(.013,-.017);shape.lineTo(.012,-.055);shape.lineTo(.028,-.067);shape.lineTo(.028,-.078);shape.lineTo(0,-.065);shape.lineTo(-.028,-.078);shape.lineTo(-.028,-.067);shape.lineTo(-.012,-.055);shape.lineTo(-.013,-.017);shape.lineTo(-.06,-.03);shape.lineTo(-.06,-.016);shape.lineTo(-.013,.015);shape.closePath();const planeGeometry=new T.ShapeGeometry(shape),planeMaterial=new T.MeshBasicMaterial({color:'#f9f6e7',side:T.DoubleSide});const plane=new T.Mesh(planeGeometry,planeMaterial);group.add(plane);
 const resize=()=>{if(disposed)return;const box=target.getBoundingClientRect();renderer.setSize(Math.max(1,box.width),Math.max(1,box.height),false);camera.aspect=box.width/Math.max(1,box.height);camera.updateProjectionMatrix();camera.updateMatrixWorld(true);};observer=new ResizeObserver(resize);observer.observe(target);resize();
 const label=v=>{const p=v.clone().applyQuaternion(group.quaternion).project(camera);return{x:(p.x+1)*50,y:(1-p.y)*50};};depart.value=label(from);arrival.value=label(to);document.addEventListener('visibilitychange',visibility);started=performance.now();
 const normal=new T.Vector3(),up=new T.Vector3(),basis=new T.Matrix4();function draw(now){if(disposed)return;frame=requestAnimationFrame(draw);if(document.hidden)return;const t=Math.min(1,(now-started-pausedMs)/8200);progress.value=t;const travel=T.MathUtils.smoothstep(t,.12,.88),pos=route(travel);plane.position.copy(pos);normal.copy(pos).normalize();up.copy(route(Math.min(.999,travel+.004))).sub(route(Math.max(.001,travel-.004))).normalize();if(up.lengthSq()<.01)up.set(0,1,0);const right=new T.Vector3().crossVectors(up,normal).normalize();up.crossVectors(normal,right).normalize();basis.makeBasis(right,up,normal);plane.quaternion.setFromRotationMatrix(basis);renderer.render(scene,camera);if(t>=1){cancelAnimationFrame(frame);emit('finish');}}
 frame=requestAnimationFrame(draw);
 // Store only owned transient resources; there is no persistent travel renderer.
 scene.userData.clean=()=>{for(const g of [pinGeometry,dotGeometry,planeGeometry])g.dispose();for(const m of [pinMaterial,dotMaterial,planeMaterial])m.dispose();};
});
onBeforeUnmount(()=>{disposed=true;cancelAnimationFrame(frame);observer?.disconnect();document.removeEventListener('visibilitychange',visibility);scene?.userData.clean?.();geometry?.dispose();material?.dispose();texture?.dispose();renderer?.dispose();renderer?.forceContextLoss();});
</script>
<template><section class="travel-screen"><header><span class="eyebrow">KTD / INTERNATIONAL ASSIGNMENTS</span><span>{{status}} <i class="live-dot"></i></span></header><div class="travel-globe"><canvas ref="canvas" aria-label="Earth with a dotted flight route and moving airplane"></canvas><span class="travel-pin departure" :style="{left:depart.x+'%',top:depart.y+'%'}">{{from.name}}</span><span class="travel-pin arrival" :style="{left:arrival.x+'%',top:arrival.y+'%'}">{{to.name}}</span></div><div class="travel-itinerary"><div><small>DEPARTURE / {{from.city}}</small><h2>{{from.name}}</h2></div><span class="flight-arrow">✈</span><div><small>ARRIVAL / {{to.city}}</small><h2>{{to.name}}</h2></div></div><p>{{to.hospital}} Medical Center · next assignment</p><div class="flight-progress"><i :style="{width:progress*100+'%'}"></i></div><button @click="emit('finish')">Skip flight →</button></section></template>
